        "457": { n: "Integrity", t: "No visible damage, cracks, etc." },
        "458": { n: "Surfacing", t: "Internal company standard (per TR EAEU 042/2017 and GOST R EN 1177-2013, impact-attenuating surfacing thickness is determined by calculation against the equipment's critical fall height and confirmed by certificate, not a fixed figure): As per the project. Level differences ≤3 mm/1 m. Rubber granulate thickness ≥4 cm (fall-zones ≥5 cm). Tolerance +0.5 cm / -0. Sand: thickness ≥15 cm. Tolerance +2 cm / -1 cm. Wood chips: thickness ≥20 cm. Tolerance +3 cm / -2 cm. No cracks, no damage." },
        "459": { n: "Playground fill, equipment", t: "As per the project. Certificate of conformity to TR EAEU 042/2017 for the equipment is mandatory." },
        "460": { n: "Equipment marking", t: "GOST R 52169-2012 cl.6.2: manufacturer name/address, year the equipment was put into service, equipment designation per 6.1" },
        "461": { n: "Sharp corners", t: "None; corner radius ≥3 mm (GOST R 52169-2012 cl.4.3.11)" },
        "462": { n: "Handrail diameter", t: "GOST R 52169-2012. Grip element 16–45 mm in any direction (cl.4.3.16) and width of a «grasp» element not more than 60 mm (cl.4.3.17)" },
        "463": { n: "Step height", t: "GOST 34995-2023 120–150 mm. Tolerance ±1 cm." },
        "464": { n: "Slide incline angle", t: "≤40° (average incline of the sliding section); maximum for an individual element ≤60°. Tolerance ±1° (GOST R 52168-2012 cl.5.5.2)" },
        "465": { n: "Side rims", t: "Internal company standard (recommendations of playground equipment manufacturers on sandbox walls). height ≥15 cm" },
        "466": { n: "Gaps between elements", t: "GOST R 52169-2012 — horizontal walking/running surfaces ≤30 mm (cl.4.3.23.9), variable gaps (springs, etc.) ≥12 mm (cl.4.3.23.10)" },
        "467": { n: "Swings", t: "GOST R 52167-2012 cl.5.4.3 Seats of soft material (rubber, plastic). Minimum distance between swings not less than 20% of the suspension length + 300 mm." },
        "468": { n: "Bolts and connections", t: "Tightened, without play. Covered with protective caps (GOST R 52301-2013 — re-tightening of bolts during inspection)" },
        "469": { n: "Integrity", t: "Metal elements with anti-corrosion coating. Wooden elements free of cracks and chips (GOST R 52301-2013 — corrosion control of metal elements during periodic inspection)." },
        "470": { n: "Benches", t: "Quantity, type as per concept/project" },
