        "605": { n: "Waterstop integrity", t: "Internal company standard (manufacturer's technical specifications (TU)). no damage" },
        "606": { n: "Waterstop cleanliness", t: "Internal company standard (manufacturer's technical specifications (TU)). Before concreting the waterstop must be thoroughly cleaned of dirt and ice" },
        "607": { n: "Installation symmetrically, centred in construction joints", t: "Internal company standard (manufacturer's technical specifications (TU)). deviation from design position ≤ 30 mm" },
        "608": { n: "Distance to the edge of the structure", t: "Internal company standard (manufacturer's technical specifications (TU)). ≥ 75 mm" },
        "609": { n: "Joint overlap value", t: "Internal company standard (manufacturer's technical specifications (TU)). ≥ 50 mm" },
        "610": { n: "Joint quality, closed loop", t: "Internal company standard (manufacturer's technical specifications (TU)). Firm connection of elements, closed loop around the full perimeter" },
        "611": { n: "Fastener installation spacing", t: "Internal company standard (manufacturer's technical specifications (TU)). From 200 to 250 mm" },
        "612": { n: "Structural interface joints", t: "Internal company standard (manufacturer's technical specifications (TU)). Not less than 30 mm" },
        "613": { n: "Surface preparation", t: "Internal company standard (manufacturer's technical specifications (TU)). The waterstop is placed on the prepared concrete surface before formwork installation, centred on the construction joint" },
        "614": { n: "Sealing of joints and corners", t: "Internal company standard (manufacturer's technical specifications (TU)). A PVC strip not less than 25 mm wide must be welded on top of the welded seam to seal and strengthen the waterstop joint (the strip is welded on both sides of the joint)" },
        "615": { n: "Waterstop connection / weld quality", t: "Internal company standard (manufacturer's technical specifications (TU)). Butt joint. Waterstop joints and corners are welded with a special welding tool. Checked against light. An electric-spark flaw detector may be used for verification" },
        "616": { n: "Waterstop integrity", t: "Internal company standard (manufacturer's technical specifications (TU)). No punctures, cuts, etc." },
        "617": { n: "Fastening spacing to the reinforcement cage", t: "Internal company standard (manufacturer's technical specifications (TU)). 200-300 mm" },
        "618": { n: "Distance to reinforcement", t: "Internal company standard (manufacturer's technical specifications (TU)). ≥ 20 mm" },
        "619": { n: "Deviation from the joint axis", t: "Internal company standard (manufacturer's technical specifications (TU)). ≤ 10 mm" },
        "620": { n: "Bend of waterstop anchors", t: "Internal company standard (manufacturer's technical specifications (TU)). ≤ 10 mm" },
        "621": { n: "Surface preparation for installation", t: "Internal company standard (manufacturer's technical specifications (TU)). The concrete surface must be cleaned of dust, soil, ice, paint and other foreign materials" },
        "622": { n: "Length of the installed section", t: "Internal company standard (manufacturer's technical specifications (TU)). ≤ 6 m" },
        "623": { n: "Overlap value", t: "Internal company standard (manufacturer's technical specifications (TU)). ≥ 150 mm" },
        "624": { n: "Fastener installation spacing", t: "Internal company standard (manufacturer's technical specifications (TU)). 150-200 mm" },
        "625": { n: "Deviation from the design position in the joint plane", t: "Internal company standard (manufacturer's technical specifications (TU)). ≤ 50 mm" },
        "626": { n: "Distance to the edge of the structure in plan", t: "Internal company standard (manufacturer's technical specifications (TU)). ≥ 75 mm" },
        "627": { n: "Distance to the surface onto which installation is performed", t: "Internal company standard (manufacturer's technical specifications (TU)). ≤ 3 mm" },
        "628": { n: "Tube connection quality", t: "Internal company standard (manufacturer's technical specifications (TU)). Firm connection of elements" },
        "629": { n: "Distance from the tube outlet to the joint", t: "Internal company standard (manufacturer's technical specifications (TU)). ≥ 200 mm" },
        "630": { n: "Box installation", t: "Availability of boxes" },
        "631": { n: "Cap installation", t: "Availability of caps" },
        "632": { n: "Mixing ratio", t: "By kit (per trial sample). Before the actual grouting, a sample is taken into a separate container and the gel time is checked" },
        "633": { n: "Tube patency", t: "Internal company standard (manufacturer's technical specifications (TU)). Full, according to pressure. Before starting injection the tube patency must be checked with water or compressed air from a compressor" },
        "634": { n: "Injection pressure", t: "≤ 80 atm. Do not let system pressure rise above 80 atm.; if necessary, inject with pauses, keeping the system pressure in the range of 20 to 40 atm" },
        "635": { n: "Injection resin consumption", t: "Internal company standard (manufacturer's technical specifications (TU)). ≤ 1.5 l/l.m." },
        "636": { n: "Injection resin exit from the joint plane", t: "Internal company standard (manufacturer's technical specifications (TU)). 50% of joint length" },
        "637": { n: "Temperature regime", t: "Internal company standard (manufacturer's technical specifications (TU)). Works are carried out at an ambient and structure-surface temperature not below +5°C." },
        "638": { n: "Caulking of holes in concrete", t: "Internal company standard (manufacturer's technical specifications (TU)). Preparatory measures to remove cones, PVC tubes, and seal holes over the full thickness of the structure with a repair compound" },
        "639": { n: "Substrate surface readiness before application", t: "Internal company standard. Surface quality (bulges, protrusions) not more than 2 mm. Voids or cavities not deeper than 5 mm are allowed; cement laitance, dirt, grease, bitumen and oil stains and other contaminants must be removed from the concrete surface" },
        "640": { n: "Joint raking and chase filling", t: "Internal company standard (manufacturer's technical specifications (TU)). In the form of a 30×30 mm chase, filled with a special shrinkage-free repair compound. Raking of joints and filling of the chase with repair compound" },
        "641": { n: "Layer thickness", t: "Internal company standard (manufacturer's technical specifications (TU)). Not less than 2 layers. The second layer is applied perpendicular to the first, thickness of one layer not less than 1 mm" },
        "642": { n: "Compliance with curing regime after application", t: "Internal company standard (manufacturer's technical specifications (TU)). For the following two days the air and substrate-surface temperature must be not below +5°C and not above +30°C. During curing (not less than 24 hours) the surface must be protected from rain, prolonged direct sunlight and freezing." },

