        "1510": { n: "Number and placement of blocks", t: "Internal company standard. Minimum 2 blocks under the vertical jambs; additional blocks every 600-700 mm; mandatory under the hinge group. For heavy doors (≥ 100 kg) - reinforced wedging. 2 wedges on each side of the vertical jambs, 1 wedge in the upper horizontal part\nDistance between wedges ≤ 600 mm." },
        "1511": { n: "Anchor installation", t: "Internal company standard. Number of fixing points: not less than 6 pcs (3 on each side); Anchor diameter: not less than 10 mm.\nAnchorage depth: not less than 100 mm" },
        "1512": { n: "Installation joint", t: "Internal company standard Joint thickness: 15-40 mm (within the normative range of 10-60 mm, GOST R 71972-2025, cl.5.3.4/6.4); use of low-expansion polyurethane foam" },
        "1513": { n: "Joint sealing (protection)", t: "As per the project, reference sample. Sealant, tape" },
        "1514": { n: "Deviation of the installed units from vertical", t: "Tolerance: ≤4 mm over the full height of the door unit. GOST R 71972-2025, cl.7.2" },
        "1515": { n: "Completeness", t: "As per the approved reference sample (locks, handle, peephole, weatherstrip, turn-buttons, casings, plates)" },
        "1516": { n: "Aesthetic appearance", t: "No chips, scratches, damage. Extension jambs and casings - tightness of fit to the wall, aesthetics of joints" },
        "1517": { n: "Hinge adjustment, seal tightness (no drafts)", t: "Internal company standard. Gap between leaf and frame: 3-5 mm; no sagging (checked with a level); no drafts. Perimeter gap: ≤ 2 mm." },
        "1518": { n: "Operation of locks and locking mechanisms", t: "Smooth movement of bolts; no key sticking" },
        "1519": { n: "Unit protection", t: "Film coating; cardboard crate for impact protection; rubber corner protectors; heavy-fabric (canvas) covers; installation of a plywood door protector (thickness 10-12 mm)" },

