        "1710": { n: "Profile fastening", t: "SP 163.1325800.2014, per KNAUF album. Self-tapping screws 3.5×9.5 mm, spacing ≤250 mm" },
        "1711": { n: "Use of hangers", t: "SP 163.1325800.2014 cl. 7.2.5.3, per the KNAUF album. Per the project. Hanger spacing: 900–1200 mm (max. 1.2 m)\nAt a load >15 kg/m²: reduce to 600 mm.\nFor multi-level ceilings: 600 mm" },
        "1712": { n: "Frame deviation from vertical (walls)", t: "SP 163.1325800.2014, per the KNAUF album\nTolerance: ≤2 mm/1 m, but ≤10 mm over the full height" },
        "1713": { n: "Frame deviation from vertical (ceilings)", t: "SP 163.1325800.2014, per the KNAUF album. For single-level ceilings: not more than 2 mm per metre of length, but not more than 10 mm over the room length\nFor multi-level and complex ceilings: not more than 1,5 mm per metre. For ceilings to be painted: not more than 1 mm per metre. For ceilings with lighting: not more than 0,5 mm per metre. Local irregularities up to 1 mm are allowed when checked with a straightedge\nFor curved elements the deviation is not more than 3 mm from the design line. In light-fixture installation zones the tolerance is tightened by 30%" },
        "1714": { n: "Profile bonding at corners", t: "SP 163.1325800.2014, per the KNAUF album\nMandatory (KNAUF album)" },
        "1715": { n: "Installation of reinforcement and blocking", t: "As per the project." },
        "1716": { n: "Gaps at floor/ceiling", t: "SP 163.1325800.2014 cl.7.1.5.14: gap between the lining and the ceiling — not less than 5 mm; between the lining and the floor — not less than 10 mm (expansion gap)" },
        "1717": { n: "Gap between boards", t: "SP 163.1325800.2014 E.6.13. 5–7 mm (for filling)" },
        "1718": { n: "Joint offset", t: "SP 163.1325800.2014 cl.7.1.5.13 Staggered ≥400 mm in adjacent rows" },
        "1719": { n: "Fastening with self-tapping screws", t: "SP 163.1325800.2014 cl.7.1.5.12: spacing ≤250 mm (staggered); head recess — about 1 mm (E.1.14, E.6.12)" },
        "1720": { n: "Substrate preparation/priming", t: "SP 163.1325800.2014 cl. 6.1a.16, 6.4.2.3\nKNAUF Betokontakt for smooth surfaces" },
        "1721": { n: "Mesh reinforcement", t: "WEP, SP 163.1325800.2014 cl.6.4.2.4\nGlass-fibre mesh 50 mm at joints, joint tape on all seams." },
        "1722": { n: "Layer thickness", t: "Internal company standard\nTolerance: 1-2 mm (base), 0.3-0.5 mm (finish)" },
        "1723": { n: "Irregularities after sanding", t: "Internal company standard Tolerance: ≤0.5 mm/2 m" },
        "1724": { n: "Corners (internal/external)", t: "Internal company standard Tolerance: perforated corner bead with ±1 mm accuracy, embedded in the coat" },
        "1725": { n: "K1", t: "Internal company standard (Table 7.5 (K1) of SP 71.13330.2017 was deleted by Amendment No.3, effective 01.02.2026): scratches, pits, tool marks up to 3 mm deep are permitted. Shadows from side lighting are permitted" },
        "1726": { n: "K2", t: "Internal company standard (Table 7.5 (K2) of SP 71.13330.2017 was deleted by Amendment No.3, effective 01.02.2026): scratches, pits, tool marks up to 1 mm deep are permitted. Shadows from side lighting are permitted" },
        "1727": { n: "K3", t: "Internal company standard (Table 7.5 (K3) of SP 71.13330.2017 was deleted by Amendment No.3, effective 01.02.2026): abrasive marks from sanding not deeper than 0.3 mm are permitted. Shadows from side lighting are permitted" },
        "1728": { n: "Access-panel location and type", t: "Per the project.\nOffset from the board edge ≥100 mm.\nFrame around the perimeter (reinforcement with UD 28/27 profile)" },
        "1729": { n: "Gap between the access panel and the gypsum board", t: "Tolerance: 2-3 mm." },
